import type { ContentPack } from '../types';
import { lesson, M, Nq, TF } from '../lib';

const P: ContentPack = {
  '2P-CM-1': lesson(['El hábitat es el lugar donde vive un ser vivo: el mar, el bosque, el desierto, el río, la ciudad… Allí encuentra comida, agua y refugio.|L’hàbitat és el lloc on viu un ésser viu: la mar, el bosc, el desert, el riu, la ciutat… Allí troba menjar, aigua i refugi.|A habitat is where a living thing lives: the sea, a forest, a desert, a river, a town… There it finds food, water and shelter.'],
    '¿Cuál es el hábitat del pez payaso?|Quin és l’hàbitat del peix pallasso?|What is the clownfish’s habitat?', ['Vive en el agua salada, entre corales.|Viu en l’aigua salada, entre coralls.|It lives in salt water among corals.', 'Su hábitat es el mar.|El seu hàbitat és la mar.|Its habitat is the sea.'], [
    M('¿Cuál es el hábitat del camello?|Quin és l’hàbitat del camell?|What is the camel’s habitat?', 'el desierto|el desert|the desert', ['el polo|el pol|the polar regions', 'el mar|la mar|the sea'], 'Aguanta mucho tiempo sin beber.|Aguanta molt de temps sense beure.|It can go a long time without drinking.', { visual: { type: 'emoji', rows: ['🐪'], big: true } }),
    M('¿Dónde vive el oso polar?|On viu l’ós polar?|Where does the polar bear live?', 'en zonas heladas|en zones gelades|in icy places', ['en la selva|en la selva|in the rainforest', 'en el desierto|en el desert|in the desert'], 'Su pelo grueso y blanco le protege del frío.|El seu pèl gruixut i blanc el protegix del fred.|Its thick white fur protects it from the cold.', { visual: { type: 'emoji', rows: ['🐻‍❄️'], big: true } }),
    M('¿Qué encuentra un animal en su hábitat?|Què troba un animal en el seu hàbitat?|What does an animal find in its habitat?', 'comida, agua y refugio|menjar, aigua i refugi|food, water and shelter', ['juguetes|joguets|toys', 'solo luz|només llum|only light'], 'Es todo lo que necesita para vivir.|És tot el que necessita per a viure.|Everything it needs to live.'),
    M('¿Cuál es el hábitat de la rana?|Quin és l’hàbitat de la granota?|What is the frog’s habitat?', 'charcas y ríos|basses i rius|ponds and rivers', ['el desierto|el desert|the desert', 'la nieve|la neu|the snow'], 'Necesita agua dulce y humedad.|Necessita aigua dolça i humitat.|It needs fresh water and damp places.', { visual: { type: 'emoji', rows: ['🐸'], big: true } }),
    TF('Si destruimos un bosque, muchos animales se quedan sin casa.|Si destruïm un bosc, molts animals es queden sense casa.|If we destroy a forest, many animals lose their homes.', true, 'El bosque es su hábitat.|El bosc és el seu hàbitat.|The forest is their habitat.'),
    M('¿Qué animal vive en la selva?|Quin animal viu en la selva?|Which animal lives in the rainforest?', 'el mono|el mico|the monkey', ['el pingüino|el pingüí|the penguin', 'el camello|el camell|the camel'], 'La selva es cálida y tiene muchos árboles.|La selva és càlida i té molts arbres.|The rainforest is warm with lots of trees.', { visual: { type: 'emoji', rows: ['🐒'], big: true } }),
  ]),
  '2P-CM-2': lesson(['Los espacios naturales (bosques, playas, ríos, montañas) son de todos. Para cuidarlos: no dejar basura, no hacer ruido, no arrancar plantas y no salir de los caminos.|Els espais naturals (boscos, platges, rius, muntanyes) són de tots. Per a cuidar-los: no deixar fem, no fer soroll, no arrancar plantes i no eixir dels camins.|Natural spaces (forests, beaches, rivers, mountains) belong to everyone. To look after them: no litter, no noise, no pulling up plants and stay on the paths.'],
    '¿Por qué no hay que hacer fuego en el bosque?|Per què no cal fer foc en el bosc?|Why must you not light fires in the forest?', ['Un fuego puede escaparse y quemar los árboles.|Un foc es pot escapar i cremar els arbres.|A fire can get out of control and burn the trees.', 'Los incendios destruyen el hábitat de muchos seres vivos.|Els incendis destruïxen l’hàbitat de molts éssers vius.|Wildfires destroy the habitat of many living things.'], [
    M('En una excursión, ¿qué haces con el papel del bocadillo?|En una excursió, què fas amb el paper de l’entrepà?|On a trip, what do you do with your sandwich wrapper?', 'Lo guardo y lo tiro en el contenedor|El guarde i el tire en el contenidor|Keep it and put it in a bin', ['Lo dejo en el suelo|El deixe en terra|Leave it on the ground', 'Lo escondo bajo una piedra|L’amague davall d’una pedra|Hide it under a stone'], 'Deja la naturaleza como la encontraste.|Deixa la natura com la vas trobar.|Leave nature as you found it.'),
    M('¿Por qué hay que ir por los caminos marcados?|Per què cal anar pels camins marcats?|Why should you stay on marked paths?', 'Para no pisar plantas ni molestar a los animales|Per a no trepitjar plantes ni molestar els animals|To avoid trampling plants or disturbing animals', ['Porque es más rápido|Perquè és més ràpid|Because it is quicker', 'Porque está prohibido correr|Perquè està prohibit córrer|Because running is banned'], 'Fuera del camino puedes romper plantas pequeñas.|Fora del camí pots trencar plantes xicotetes.|Off the path you may crush small plants.'),
    TF('Gritar en el bosque asusta a los animales.|Cridar en el bosc espanta els animals.|Shouting in the forest scares animals.', true, 'Los animales salvajes huyen del ruido.|Els animals salvatges fugen del soroll.|Wild animals run away from noise.'),
    TF('Se pueden llevar a casa conchas y plantas de un parque natural.|Es poden emportar a casa petxines i plantes d’un parc natural.|You may take shells and plants home from a nature reserve.', false, 'Forman parte del ecosistema.|Formen part de l’ecosistema.|They are part of the ecosystem.'),
    M('¿Qué es un parque natural?|Què és un parc natural?|What is a nature reserve?', 'Un espacio natural protegido|Un espai natural protegit|A protected natural area', ['Un parque de juegos|Un parc de jocs|A playground', 'Un zoo|Un zoo|A zoo'], 'Se protege por su valor natural.|Es protegix pel seu valor natural.|It is protected because of its natural value.'),
    M('Ves basura en la orilla del río. ¿Qué puedes hacer?|Veus fem a la vora del riu. Què pots fer?|You see litter by the river. What can you do?', 'Avisar a un adulto y recogerla con guantes|Avisar un adult i arreplegar-lo amb guants|Tell an adult and pick it up with gloves', ['Tirarla al río|Tirar-lo al riu|Throw it in the river', 'Nada|Res|Nothing'], 'Cuidar la naturaleza es tarea de todos.|Cuidar la natura és tasca de tots.|Caring for nature is everyone’s job.'),
  ]),
  '2P-CM-3': lesson(['Algunas enfermedades comunes son el resfriado, la gripe o la gastroenteritis. Muchas las causan gérmenes que pasan de una persona a otra.|Algunes malalties comunes són el refredat, la grip o la gastroenteritis. Moltes les causen gèrmens que passen d’una persona a una altra.|Some common illnesses are colds, flu and stomach bugs. Many are caused by germs that pass from person to person.', 'Para evitarlas: lavarse las manos, taparse al toser, ventilar la clase y vacunarse.|Per a evitar-les: llavar-se les mans, tapar-se en tossir, ventilar la classe i vacunar-se.|To prevent them: wash your hands, cover your cough, air the classroom and get vaccinated.'],
    '¿Cómo se debe toser?|Com s’ha de tossir?|How should you cough?', ['Al toser salen gotitas con gérmenes.|En tossir ixen gotetes amb gèrmens.|Coughing sends out tiny droplets with germs.', 'Tapándome con el codo.|Tapant-me amb el colze.|Into my elbow.'], [
    M('¿Qué ayuda más a no contagiar un resfriado?|Què ajuda més a no contagiar un refredat?|What best helps stop a cold spreading?', 'Lavarse las manos a menudo|Llavar-se les mans sovint|Washing hands often', ['Compartir el vaso|Compartir el got|Sharing a cup', 'No ventilar nunca|No ventilar mai|Never opening windows'], 'El jabón elimina los gérmenes.|El sabó elimina els gèrmens.|Soap gets rid of germs.'),
    M('¿Para qué sirven las vacunas?|Per a què servixen les vacunes?|What are vaccines for?', 'Para protegernos de algunas enfermedades|Per a protegir-nos d’algunes malalties|To protect us from some illnesses', ['Para crecer más|Per a créixer més|To grow taller', 'Para no dormir|Per a no dormir|To stay awake'], 'Enseñan al cuerpo a defenderse.|Ensenyen el cos a defendre’s.|They teach the body to defend itself.'),
    TF('Si estoy enfermo, es mejor quedarme en casa y descansar.|Si estic malalt, és millor quedar-me a casa i descansar.|If I am ill, it is better to stay home and rest.', true, 'Así te recuperas y no contagias a otros.|Així et recuperes i no contagies els altres.|You recover and do not infect others.'),
    M('¿Quién te puede curar si estás enfermo?|Qui et pot curar si estàs malalt?|Who can help you get better when you are ill?', 'el médico o la médica|el metge o la metgessa|a doctor', ['el cartero|el carter|the postman', 'el panadero|el forner|the baker'], 'Es su trabajo.|És la seua faena.|It is their job.'),
    M('¿Qué hay que hacer al estornudar?|Què cal fer en esternudar?|What should you do when you sneeze?', 'Taparse con un pañuelo o el codo|Tapar-se amb un mocador o el colze|Cover your nose with a tissue or elbow', ['Estornudar hacia los demás|Esternudar cap als altres|Sneeze towards other people', 'Taparse con la mano y tocarlo todo|Tapar-se amb la mà i tocar-ho tot|Use your hand and touch everything'], 'Así los gérmenes no llegan a otros.|Així els gèrmens no arriben als altres.|That stops germs reaching others.'),
    TF('Los medicamentos se pueden tomar sin que lo diga un adulto.|Els medicaments es poden prendre sense que ho diga un adult.|You can take medicine without an adult saying so.', false, 'Solo los da un adulto, cuando lo indica el médico.|Només els dona un adult, quan ho indica el metge.|Only an adult gives them, when a doctor says so.'),
  ]),
  '2P-CM-4': lesson(['Comer bien es comer de todo y en cantidad adecuada: frutas, verduras, legumbres, cereales, leche, huevo, pescado y carne. Los dulces, solo de vez en cuando.|Menjar bé és menjar de tot i en quantitat adequada: fruites, verdures, llegums, cereals, llet, ou, peix i carn. Els dolços, només de tant en tant.|Eating well means eating a bit of everything in the right amounts: fruit, vegetables, pulses, cereals, milk, eggs, fish and meat. Sweets only now and then.', 'Dormir unas 10 horas ayuda a crecer, a aprender y a estar de buen humor.|Dormir unes 10 hores ajuda a créixer, a aprendre i a estar de bon humor.|Sleeping about 10 hours helps you grow, learn and stay in a good mood.'],
    '¿Qué desayuno es más completo?|Quin desdejuni és més complet?|Which breakfast is more balanced?', ['Necesito un lácteo, un cereal y una fruta.|Necessite un lacti, un cereal i una fruita.|I need dairy, a cereal and fruit.', 'Leche, pan con aceite y una naranja.|Llet, pa amb oli i una taronja.|Milk, bread with olive oil and an orange.'], [
    M('¿Qué alimento conviene comer solo de vez en cuando?|Quin aliment convé menjar només de tant en tant?|Which food should you eat only now and then?', 'pasteles|pastissos|cakes', ['fruta|fruita|fruit', 'verdura|verdura|vegetables'], 'Tienen mucho azúcar.|Tenen molt de sucre.|They have a lot of sugar.'),
    M('¿Cuántas horas debe dormir un niño de 7 años?|Quantes hores ha de dormir un xiquet de 7 anys?|How many hours should a 7-year-old sleep?', 'unas 10 horas|unes 10 hores|about 10 hours', ['3 horas|3 hores|3 hours', '20 horas|20 hores|20 hours'], 'Los niños necesitan dormir mucho.|Els xiquets necessiten dormir molt.|Children need lots of sleep.'),
    M('Las lentejas y los garbanzos son…|Les llentilles i els cigrons són…|Lentils and chickpeas are…', 'legumbres|llegums|pulses', ['frutas|fruites|fruit', 'dulces|dolços|sweets'], 'Se suelen comer en guiso.|Se solen menjar en guisat.|They are often eaten in stews.'),
    TF('Saltarse el desayuno ayuda a rendir en clase.|Botar-se el desdejuni ajuda a rendir en classe.|Skipping breakfast helps you do well in class.', false, 'El desayuno da energía para la mañana.|El desdejuni dona energia per al matí.|Breakfast gives you energy for the morning.'),
    M('¿Qué es mejor antes de dormir?|Què és millor abans de dormir?|What is best before bedtime?', 'leer un cuento|llegir un conte|reading a story', ['jugar con la tableta|jugar amb la tauleta|playing on a tablet', 'tomar un refresco|prendre un refresc|having a fizzy drink'], 'Las pantallas y el azúcar quitan el sueño.|Les pantalles i el sucre lleven la son.|Screens and sugar keep you awake.'),
    M('¿Qué alimento da más vitaminas?|Quin aliment dona més vitamines?|Which food gives more vitamins?', 'una mandarina|una mandarina|a tangerine', ['unas patatas fritas de bolsa|unes creïlles fregides de bossa|a bag of crisps', 'una golosina|una llepolia|a sweet'], 'Las frutas tienen muchas vitaminas.|Les fruites tenen moltes vitamines.|Fruit is full of vitamins.'),
  ]),
  '2P-CM-5': lesson(['Cada material tiene propiedades: puede ser duro o blando, flexible o rígido, transparente u opaco, impermeable o absorbente.|Cada material té propietats: pot ser dur o blan, flexible o rígid, transparent o opac, impermeable o absorbent.|Each material has properties: hard or soft, bendy or stiff, see-through or opaque, waterproof or absorbent.', 'Elegimos el material según para qué lo queremos.|Triem el material segons per a què el volem.|We choose a material for what we need it to do.'],
    '¿De qué material harías una toalla?|De quin material faries una tovallola?|What material would you make a towel from?', ['Una toalla tiene que secar: absorber el agua.|Una tovallola ha d’eixugar: absorbir l’aigua.|A towel has to dry you: soak up water.', 'De algodón, que es absorbente.|De cotó, que és absorbent.|From cotton, which is absorbent.'], [
    M('¿Qué material es flexible?|Quin material és flexible?|Which material is bendy?', 'la goma|la goma|rubber', ['el vidrio|el vidre|glass', 'la piedra|la pedra|stone'], 'Se dobla sin romperse.|Es doblega sense trencar-se.|It bends without breaking.'),
    M('¿Qué material es opaco (no deja pasar la luz)?|Quin material és opac (no deixa passar la llum)?|Which material is opaque (does not let light through)?', 'la madera|la fusta|wood', ['el vidrio|el vidre|glass', 'el plástico transparente|el plàstic transparent|clear plastic'], 'No ves a través de él.|No veus a través d’ell.|You cannot see through it.'),
    M('Un chubasquero tiene que ser…|Un impermeable ha de ser…|A raincoat has to be…', 'impermeable|impermeable|waterproof', ['absorbente|absorbent|absorbent', 'transparente|transparent|see-through'], 'No debe dejar pasar el agua.|No ha de deixar passar l’aigua.|It must not let water through.'),
    M('¿Qué material es más duro?|Quin material és més dur?|Which material is harder?', 'el hierro|el ferro|iron', ['la esponja|l’esponja|sponge', 'la lana|la llana|wool'], 'Duro: no se raya ni se aplasta fácilmente.|Dur: no es ratlla ni s’aixafa fàcilment.|Hard: it does not scratch or squash easily.'),
    M('¿Por qué las ollas son de metal?|Per què les olles són de metall?|Why are pots made of metal?', 'Aguanta el calor y lo transmite a la comida|Aguanta la calor i la transmet al menjar|It can take the heat and pass it to the food', ['Porque es transparente|Perquè és transparent|Because it is see-through', 'Porque es blando|Perquè és blan|Because it is soft'], 'Los metales conducen bien el calor.|Els metalls conduïxen bé la calor.|Metals conduct heat well.'),
    M('La lana, ¿de dónde viene?|La llana, d’on ve?|Where does wool come from?', 'de las ovejas (natural)|de les ovelles (natural)|from sheep (natural)', ['de una fábrica de plástico|d’una fàbrica de plàstic|from a plastic factory', 'de las piedras|de les pedres|from stones'], 'Es un material natural de origen animal.|És un material natural d’origen animal.|It is a natural material from an animal.'),
  ]),
  '2P-CM-6': lesson(['Una estructura es un conjunto de piezas que aguanta peso y mantiene la forma: un puente, una torre, una silla, el esqueleto.|Una estructura és un conjunt de peces que aguanta pes i manté la forma: un pont, una torre, una cadira, l’esquelet.|A structure is a set of parts that holds weight and keeps its shape: a bridge, a tower, a chair, a skeleton.', 'Los triángulos hacen las estructuras más fuertes. Una base ancha las hace más estables.|Els triangles fan les estructures més fortes. Una base ampla les fa més estables.|Triangles make structures stronger. A wide base makes them more stable.'],
    '¿Por qué las torres eléctricas tienen muchos triángulos?|Per què les torres elèctriques tenen molts triangles?|Why do electricity pylons have lots of triangles?', ['Un triángulo no se deforma al empujarlo.|Un triangle no es deforma en empentar-lo.|A triangle does not change shape when pushed.', 'Así la torre es más fuerte.|Així la torre és més forta.|So the tower is stronger.'], [
    M('¿Qué figura hace más fuerte una estructura?|Quina figura fa més forta una estructura?|Which shape makes a structure stronger?', 'el triángulo|el triangle|the triangle', ['el círculo|el cercle|the circle', 'el cuadrado sin refuerzo|el quadrat sense reforç|an unbraced square'], 'El triángulo no se deforma.|El triangle no es deforma.|A triangle keeps its shape.'),
    M('¿Qué torre es más estable?|Quina torre és més estable?|Which tower is more stable?', 'la de base ancha|la de base ampla|the one with a wide base', ['la de base estrecha|la de base estreta|the one with a narrow base', 'la torcida|la torta|the crooked one'], 'Una base ancha impide que vuelque.|Una base ampla impedix que bolque.|A wide base stops it toppling.'),
    M('¿Cuál de estas cosas es una estructura?|Quina d’estes coses és una estructura?|Which of these is a structure?', 'un puente|un pont|a bridge', ['un charco|un bassal|a puddle', 'una nube|un núvol|a cloud'], 'Aguanta el peso de los coches.|Aguanta el pes dels cotxes.|It holds the weight of cars.'),
    TF('El esqueleto es la estructura de nuestro cuerpo.|L’esquelet és l’estructura del nostre cos.|The skeleton is our body’s structure.', true, 'Nos sostiene y nos protege.|Ens sosté i ens protegix.|It holds us up and protects us.'),
    M('Para construir un puente de papel resistente, ¿qué haces con el papel?|Per a construir un pont de paper resistent, què fas amb el paper?|To build a strong paper bridge, what do you do with the paper?', 'Doblarlo en acordeón|Doblegar-lo en acordió|Fold it like a fan', ['Mojarlo|Banyar-lo|Wet it', 'Arrugarlo|Arrugar-lo|Crumple it'], 'Los pliegues lo hacen más rígido.|Els plecs el fan més rígid.|The folds make it stiffer.'),
    M('¿Qué pieza de una silla aguanta tu peso?|Quina peça d’una cadira aguanta el teu pes?|Which parts of a chair hold your weight?', 'las patas|les potes|the legs', ['el color|el color|the colour', 'el cojín decorativo|el coixí decoratiu|the decorative cushion'], 'Las patas llevan el peso al suelo.|Les potes porten el pes al terra.|The legs carry the weight to the floor.'),
  ]),
  '2P-CM-7': lesson(['En casa usamos muchos aparatos (lavadora, nevera, teléfono, ordenador) que nos ayudan cada día. Hay que usarlos con cuidado y apagarlos si no se usan.|A casa usem molts aparells (rentadora, frigorífic, telèfon, ordinador) que ens ajuden cada dia. Cal usar-los amb compte i apagar-los si no s’usen.|At home we use many appliances (washing machine, fridge, phone, computer) that help us every day. Use them carefully and switch them off when not in use.', 'Para comunicarnos bien con otros, por teléfono o por mensaje, hay que ser amables, claros y respetuosos.|Per a comunicar-nos bé amb altres, per telèfon o per missatge, cal ser amables, clars i respectuosos.|To communicate well, on the phone or by message, be kind, clear and respectful.'],
    '¿Para qué sirve la nevera?|Per a què servix el frigorífic?|What is a fridge for?', ['Mantiene la comida fría.|Manté el menjar fred.|It keeps food cold.', 'Así los alimentos duran más.|Així els aliments duren més.|So food lasts longer.'], [
    M('¿Qué aparato sirve para lavar la ropa?|Quin aparell servix per a llavar la roba?|Which appliance washes clothes?', 'la lavadora|la rentadora|the washing machine', ['el horno|el forn|the oven', 'la nevera|el frigorífic|the fridge'], 'Usa agua y jabón.|Usa aigua i sabó.|It uses water and soap.'),
    M('Al escribir un mensaje a un amigo, ¿qué es importante?|En escriure un missatge a un amic, què és important?|When you write a message to a friend, what matters?', 'Ser amable y claro|Ser amable i clar|Being kind and clear', ['Escribir todo en mayúsculas|Escriure-ho tot en majúscules|Writing everything in capitals', 'Insultar|Insultar|Being rude'], 'Escribir en mayúsculas parece que gritas.|Escriure en majúscules sembla que crides.|Capitals look like shouting.'),
    TF('Hay que desenchufar el cargador cuando no se usa.|Cal desendollar el carregador quan no s’usa.|You should unplug the charger when not in use.', true, 'Así ahorras energía.|Així estalvies energia.|That saves energy.'),
    M('¿Qué aparato usamos para hablar con alguien que está lejos?|Quin aparell usem per a parlar amb algú que està lluny?|Which device do we use to talk to someone far away?', 'el teléfono|el telèfon|the phone', ['la tostadora|la torradora|the toaster', 'la aspiradora|l’aspiradora|the vacuum cleaner'], 'Sirve para comunicarse.|Servix per a comunicar-se.|It is for communicating.'),
    M('Un aparato hace chispas. ¿Qué haces?|Un aparell fa espurnes. Què fas?|An appliance is sparking. What do you do?', 'Me alejo y aviso a un adulto|M’allunye i avise un adult|Move away and tell an adult', ['Lo toco|El toque|Touch it', 'Le echo agua|Li tire aigua|Pour water on it'], 'La electricidad es peligrosa.|L’electricitat és perillosa.|Electricity is dangerous.'),
    M('¿Para qué sirve la tecnología en casa?|Per a què servix la tecnologia a casa?|What is technology at home for?', 'Para facilitarnos las tareas|Per a facilitar-nos les tasques|To make jobs easier', ['Para ensuciar|Per a embrutar|To make a mess', 'Para nada|Per a res|For nothing'], 'Los aparatos nos ahorran trabajo.|Els aparells ens estalvien treball.|Appliances save us work.'),
  ]),
  '2P-CM-8': lesson(['Para resolver un problema como un ingeniero: 1) observo el problema; 2) pienso ideas; 3) dibujo la mejor; 4) la construyo; 5) la pruebo y la mejoro.|Per a resoldre un problema com un enginyer: 1) observe el problema; 2) pense idees; 3) dibuixe la millor; 4) la construïsc; 5) la prove i la millore.|To solve a problem like an engineer: 1) look at the problem; 2) think of ideas; 3) draw the best one; 4) build it; 5) test and improve it.'],
    'Las pinturas se caen de la mesa. ¿Qué diseño haces?|Les pintures cauen de la taula. Quin disseny fas?|The crayons keep falling off the table. What do you design?', ['Pienso ideas: una caja, un vaso, un estuche.|Pense idees: una caixa, un got, un estoig.|I think of ideas: a box, a pot, a pencil case.', 'Construyo un bote con un rollo de cartón y lo pruebo.|Construïsc un pot amb un rotlle de cartó i el prove.|I build a pot from a cardboard tube and test it.'], [
    M('¿Qué haces primero en un proyecto de diseño?|Què fas primer en un projecte de disseny?|What do you do first in a design project?', 'Observar bien el problema|Observar bé el problema|Look carefully at the problem', ['Construir sin pensar|Construir sense pensar|Build without thinking', 'Probarlo|Provar-ho|Test it'], 'Primero hay que entender qué pasa.|Primer cal entendre què passa.|First you need to understand what is going on.'),
    M('¿Qué haces si tu invento no funciona bien?|Què fas si el teu invent no funciona bé?|What do you do if your invention does not work well?', 'Lo mejoro y lo vuelvo a probar|El millore i el torne a provar|Improve it and test it again', ['Lo tiro y me enfado|El tire i m’enfade|Throw it away and get cross', 'Digo que funciona|Dic que funciona|Say it works'], 'Equivocarse es parte de inventar.|Equivocar-se és part d’inventar.|Mistakes are part of inventing.'),
    M('¿Para qué sirve dibujar la idea antes de construir?|Per a què servix dibuixar la idea abans de construir?|Why draw the idea before building it?', 'Para planear qué materiales y pasos necesito|Per a planificar quins materials i passos necessite|To plan the materials and steps I need', ['Para perder tiempo|Per a perdre temps|To waste time', 'Para no construir nada|Per a no construir res|So I never build anything'], 'El dibujo es un plan.|El dibuix és un pla.|The drawing is a plan.'),
    M('¿Qué material reciclado sirve para hacer un bote de lápices?|Quin material reciclat servix per a fer un pot de llapis?|Which recycled material is good for a pencil pot?', 'un rollo de cartón|un rotlle de cartó|a cardboard tube', ['una hoja seca|una fulla seca|a dry leaf', 'un cubito de hielo|un glaçó|an ice cube'], 'Debe ser resistente y tener forma de recipiente.|Ha de ser resistent i tindre forma de recipient.|It needs to be strong and shaped like a container.'),
    TF('Un problema grande se resuelve mejor dividiéndolo en partes pequeñas.|Un problema gran es resol millor dividint-lo en parts xicotetes.|A big problem is easier to solve when split into small parts.', true, 'Cada parte pequeña es más fácil.|Cada part xicoteta és més fàcil.|Each small part is easier.'),
    M('Con tijeras y pegamento, ¿qué norma es importante?|Amb tisores i pegament, quina norma és important?|With scissors and glue, which rule matters?', 'Usarlos con cuidado y recogerlos al acabar|Usar-los amb compte i arreplegar-los en acabar|Use them carefully and tidy up after', ['Correr con las tijeras|Córrer amb les tisores|Run with scissors', 'Dejar el pegamento abierto|Deixar el pegament obert|Leave the glue open'], 'La seguridad va primero.|La seguretat va primer.|Safety comes first.'),
  ]),
  '2P-CM-9': lesson(['Un robot sencillo sigue órdenes una a una: avanzar, retroceder, girar a la derecha o a la izquierda. Si una orden está mal, el robot no llega a su destino.|Un robot senzill seguix ordres una a una: avançar, retrocedir, girar a la dreta o a l’esquerra. Si una ordre està malament, el robot no arriba al seu destí.|A simple robot follows instructions one by one: forward, back, turn right or left. If one instruction is wrong, the robot does not reach its goal.', 'Encontrar y arreglar el error se llama depurar.|Trobar i arreglar l’error es diu depurar.|Finding and fixing the mistake is called debugging.'],
    'El robot debe llegar a la estrella: 🤖 ⬜ ⬜ ⭐. ¿Qué órdenes le das?|El robot ha d’arribar a l’estrela: 🤖 ⬜ ⬜ ⭐. Quines ordres li dones?|The robot must reach the star: 🤖 ⬜ ⬜ ⭐. What instructions do you give?', ['La estrella está 3 casillas a la derecha.|L’estrela està 3 caselles a la dreta.|The star is 3 squares to the right.', '➡️ ➡️ ➡️|➡️ ➡️ ➡️|➡️ ➡️ ➡️'], [
    Nq('🤖 ⬜ ⬜ ⬜ ⭐. ¿Cuántas veces ➡️ necesita el robot?|🤖 ⬜ ⬜ ⬜ ⭐. Quantes vegades ➡️ necessita el robot?|🤖 ⬜ ⬜ ⬜ ⭐. How many ➡️ does the robot need?', 4, [3, 5, 2], 'Cuenta las casillas hasta la estrella.|Compta les caselles fins a l’estrela.|Count the squares up to the star.'),
    M('El robot debía ir ➡️ ➡️ y fue ➡️ ⬅️. ¿Qué orden está mal?|El robot havia d’anar ➡️ ➡️ i va anar ➡️ ⬅️. Quina ordre està malament?|The robot should have gone ➡️ ➡️ but went ➡️ ⬅️. Which instruction is wrong?', 'la segunda|la segona|the second', ['la primera|la primera|the first', 'ninguna|cap|neither'], 'Compara orden por orden.|Compara ordre per ordre.|Compare instruction by instruction.'),
    M('Encontrar y arreglar un error en las órdenes se llama…|Trobar i arreglar un error en les ordres es diu…|Finding and fixing a mistake in the instructions is called…', 'depurar|depurar|debugging', ['dibujar|dibuixar|drawing', 'olvidar|oblidar|forgetting'], 'Como los programadores.|Com els programadors.|As programmers do.'),
    M('¿Qué hace la orden ⬆️?|Què fa l’ordre ⬆️?|What does the ⬆️ instruction do?', 'avanzar una casilla hacia arriba|avançar una casella cap amunt|move one square up', ['girar|girar|turn', 'pararse|parar-se|stop'], 'Mira hacia dónde apunta.|Mira cap a on apunta.|Look where it points.'),
    TF('Un robot entiende lo que queremos aunque no le demos órdenes.|Un robot entén el que volem encara que no li donem ordres.|A robot understands what we want even without instructions.', false, 'Solo hace lo que le ordenamos.|Només fa el que li ordenem.|It only does what we tell it.'),
    Nq('El robot está en la casilla 2 y recibe ➡️ ➡️ ➡️ ⬅️. ¿En qué casilla acaba?|El robot està en la casella 2 i rep ➡️ ➡️ ➡️ ⬅️. En quina casella acaba?|The robot is on square 2 and gets ➡️ ➡️ ➡️ ⬅️. Which square does it end on?', 4, [5, 6, 3], 'Tres adelante y uno atrás.|Tres avant i un arrere.|Three forward and one back.'),
  ]),
  '2P-CM-10': lesson(['Un plano es un dibujo de un lugar visto desde arriba, más pequeño que en la realidad. En él vemos dónde está cada cosa.|Un plànol és un dibuix d’un lloc vist des de dalt, més xicotet que en la realitat. En ell veiem on està cada cosa.|A plan is a drawing of a place seen from above, smaller than in real life. It shows where everything is.', 'La leyenda explica qué significa cada símbolo.|La llegenda explica què significa cada símbol.|The key explains what each symbol means.'],
    'En el plano de la clase, ¿cómo se ve una mesa?|En el plànol de la classe, com es veu una taula?|On a plan of the classroom, what does a table look like?', ['El plano se dibuja desde arriba.|El plànol es dibuixa des de dalt.|A plan is drawn from above.', 'Se ve como un rectángulo.|Es veu com un rectangle.|It looks like a rectangle.'], [
    M('¿Desde dónde se dibuja un plano?|Des d’on es dibuixa un plànol?|From where is a plan drawn?', 'desde arriba|des de dalt|from above', ['desde un lado|des d’un costat|from the side', 'desde abajo|des de baix|from below'], 'Como si fueras un pájaro.|Com si fores un pardal.|As if you were a bird.'),
    M('¿Para qué sirve la leyenda de un plano?|Per a què servix la llegenda d’un plànol?|What is the key on a plan for?', 'Para saber qué significa cada símbolo|Per a saber què significa cada símbol|To know what each symbol means', ['Para contar un cuento|Per a contar un conte|To tell a story', 'Para colorear|Per a pintar|For colouring'], 'Explica los dibujos del plano.|Explica els dibuixos del plànol.|It explains the drawings on the plan.'),
    M('Un plano es… que el lugar real.|Un plànol és… que el lloc real.|A plan is… than the real place.', 'más pequeño|més xicotet|smaller', ['más grande|més gran|bigger', 'igual de grande|igual de gran|the same size'], 'Si no, no cabría en un papel.|Si no, no cabria en un paper.|Otherwise it would not fit on paper.'),
    M('En el plano del cole, la 🛝 indica…|En el plànol de l’escola, el 🛝 indica…|On the school plan, 🛝 shows…', 'el patio de juegos|el pati de jocs|the playground', ['el comedor|el menjador|the dining hall', 'la biblioteca|la biblioteca|the library'], 'Es un tobogán.|És un tobogan.|It is a slide.'),
    TF('En un plano, la puerta de casa se puede dibujar con un símbolo.|En un plànol, la porta de casa es pot dibuixar amb un símbol.|On a plan, the front door can be shown with a symbol.', true, 'Los símbolos simplifican el dibujo.|Els símbols simplifiquen el dibuix.|Symbols make the drawing simpler.'),
    M('¿Qué usarías para ir de tu casa al parque sin perderte?|Què usaries per a anar de casa al parc sense perdre’t?|What would you use to get from home to the park without getting lost?', 'un plano del barrio|un plànol del barri|a map of the neighbourhood', ['un calendario|un calendari|a calendar', 'un reloj|un rellotge|a clock'], 'Muestra las calles.|Mostra els carrers.|It shows the streets.'),
  ]),
  '2P-CM-11': lesson(['La Tierra tiene forma casi de esfera. El globo terráqueo la representa en pequeño; el mapa la dibuja en plano.|La Terra té forma quasi d’esfera. El globus terraqüi la representa en xicotet; el mapa la dibuixa en pla.|The Earth is almost a sphere. A globe shows it small; a map draws it flat.', 'En los mapas, el azul es agua (mares y océanos) y los otros colores son tierra (continentes).|En els mapes, el blau és aigua (mars i oceans) i els altres colors són terra (continents).|On maps, blue is water (seas and oceans) and the other colours are land (continents).'],
    '¿Qué hay más en la Tierra, agua o tierra?|Què hi ha més en la Terra, aigua o terra?|Is there more water or land on Earth?', ['En el globo casi todo es azul.|En el globus quasi tot és blau.|On a globe almost everything is blue.', 'Hay mucha más agua.|Hi ha molta més aigua.|There is much more water.'], [
    M('¿Qué forma tiene la Tierra?|Quina forma té la Terra?|What shape is the Earth?', 'casi una esfera|quasi una esfera|almost a sphere', ['plana|plana|flat', 'un cubo|un cub|a cube'], 'Como una pelota un poco achatada.|Com una pilota un poc aixafada.|Like a slightly squashed ball.', { visual: { type: 'emoji', rows: ['🌍'], big: true } }),
    M('En un mapa, ¿qué indica el color azul?|En un mapa, què indica el color blau?|On a map, what does blue show?', 'agua|aigua|water', ['montañas|muntanyes|mountains', 'ciudades|ciutats|cities'], 'Mares, océanos, ríos y lagos.|Mars, oceans, rius i llacs.|Seas, oceans, rivers and lakes.'),
    M('¿Cómo se llama la bola que representa la Tierra?|Com es diu la bola que representa la Terra?|What is the ball that shows the Earth called?', 'globo terráqueo|globus terraqüi|a globe', ['brújula|brúixola|a compass', 'calendario|calendari|a calendar'], 'Puede girar como la Tierra.|Pot girar com la Terra.|It can spin like the Earth.'),
    M('¿Qué es un continente?|Què és un continent?|What is a continent?', 'una gran extensión de tierra|una gran extensió de terra|a huge area of land', ['un río|un riu|a river', 'una nube|un núvol|a cloud'], 'Europa, Asia, África, América, Oceanía y la Antártida.|Europa, Àsia, Àfrica, Amèrica, Oceania i l’Antàrtida.|Europe, Asia, Africa, the Americas, Oceania and Antarctica.'),
    TF('España está en Europa.|Espanya està a Europa.|Spain is in Europe.', true, 'Está en el sur de Europa.|Està al sud d’Europa.|It is in southern Europe.'),
    M('¿Qué ventaja tiene un mapa frente al globo?|Quin avantatge té un mapa davant del globus?|What is one advantage of a map over a globe?', 'Se puede doblar y llevar|Es pot doblegar i portar|You can fold it and carry it', ['Es redondo|És redó|It is round', 'Gira|Gira|It spins'], 'Es plano.|És pla.|It is flat.'),
  ]),
  '2P-CM-12': lesson(['El tiempo atmosférico es cómo está el cielo un día: soleado, nublado, lluvioso, con viento… Lo medimos con instrumentos.|El temps atmosfèric és com està el cel un dia: assolellat, ennuvolat, plujós, amb vent… El mesurem amb instruments.|The weather is what the sky is like on a day: sunny, cloudy, rainy, windy… We measure it with instruments.', 'El termómetro mide la temperatura; el pluviómetro, la lluvia; la veleta, la dirección del viento.|El termòmetre mesura la temperatura; el pluviòmetre, la pluja; el penell, la direcció del vent.|A thermometer measures temperature; a rain gauge, rainfall; a weather vane, wind direction.'],
    '¿Con qué medimos si hace frío o calor?|Amb què mesurem si fa fred o calor?|What do we use to measure whether it is hot or cold?', ['El calor y el frío son la temperatura.|La calor i el fred són la temperatura.|Hot and cold are temperature.', 'Con el termómetro.|Amb el termòmetre.|With a thermometer.'], [
    M('¿Qué instrumento mide la lluvia que cae?|Quin instrument mesura la pluja que cau?|Which instrument measures rainfall?', 'el pluviómetro|el pluviòmetre|a rain gauge', ['el termómetro|el termòmetre|a thermometer', 'la veleta|el penell|a weather vane'], '«Pluvia» quiere decir lluvia.|«Pluvia» vol dir pluja.|"Pluvia" means rain.'),
    M('¿Qué indica la veleta?|Què indica el penell?|What does a weather vane show?', 'de dónde viene el viento|d’on ve el vent|which way the wind blows', ['la temperatura|la temperatura|the temperature', 'la hora|l’hora|the time'], 'Gira con el viento.|Gira amb el vent.|It turns with the wind.'),
    M('El cielo está lleno de nubes grises. ¿Cómo está?|El cel està ple de núvols grisos. Com està?|The sky is full of grey clouds. What is the weather like?', 'nublado|ennuvolat|cloudy', ['soleado|assolellat|sunny', 'despejado|serè|clear'], 'Hay muchas nubes.|Hi ha molts núvols.|There are lots of clouds.', { visual: { type: 'emoji', rows: ['☁️☁️☁️'], big: true } }),
    Nq('El termómetro marca 25 °C por la tarde y 15 °C por la mañana. ¿Cuántos grados ha subido?|El termòmetre marca 25 °C per la vesprada i 15 °C pel matí. Quants graus ha pujat?|The thermometer shows 15 °C in the morning and 25 °C in the afternoon. How many degrees has it risen?', 10, [40, 15, 5], 'Resta las dos temperaturas.|Resta les dues temperatures.|Subtract the two temperatures.'),
    M('¿Por qué apuntamos el tiempo cada día en una tabla?|Per què apuntem el temps cada dia en una taula?|Why do we record the weather every day in a table?', 'Para ver cómo cambia y comparar|Per a veure com canvia i comparar|To see how it changes and compare', ['Para adivinar números|Per a endevinar nombres|To guess numbers', 'Porque sí|Perquè sí|For no reason'], 'Los datos sirven para comparar.|Les dades servixen per a comparar.|Data let us compare.'),
    TF('El tiempo atmosférico es igual todos los días.|El temps atmosfèric és igual tots els dies.|The weather is the same every day.', false, 'Cambia de un día a otro.|Canvia d’un dia a l’altre.|It changes from day to day.'),
  ]),
  '2P-CM-13': lesson(['El clima de la Tierra se está calentando: es el cambio climático. Lo causan sobre todo los gases que salen al quemar petróleo, gas y carbón en coches, fábricas y calefacciones.|El clima de la Terra s’està escalfant: és el canvi climàtic. El causen sobretot els gasos que ixen en cremar petroli, gas i carbó en cotxes, fàbriques i calefaccions.|The Earth’s climate is getting warmer: this is climate change. It is caused mainly by gases released when oil, gas and coal are burnt in cars, factories and heating.', 'Por eso hay más olas de calor, sequías y lluvias muy fuertes, y el hielo de los polos se derrite.|Per això hi ha més onades de calor, sequeres i pluges molt fortes, i el gel dels pols es fon.|That is why there are more heatwaves, droughts and heavy downpours, and polar ice is melting.'],
    '¿Qué podemos hacer para ayudar?|Què podem fer per a ajudar?|What can we do to help?', ['Quemar menos combustible ayuda.|Cremar menys combustible ajuda.|Burning less fuel helps.', 'Ir andando o en bici, apagar luces y reciclar.|Anar a peu o amb bici, apagar llums i reciclar.|Walk or cycle, switch off lights and recycle.'], [
    M('¿Qué causa principalmente el cambio climático?|Què causa principalment el canvi climàtic?|What mainly causes climate change?', 'quemar petróleo, gas y carbón|cremar petroli, gas i carbó|burning oil, gas and coal', ['plantar árboles|plantar arbres|planting trees', 'la luz de la luna|la llum de la lluna|moonlight'], 'Al quemarlos salen gases que calientan la Tierra.|En cremar-los ixen gasos que escalfen la Terra.|Burning them releases gases that warm the Earth.'),
    M('¿Qué ayuda a frenar el cambio climático?|Què ajuda a frenar el canvi climàtic?|What helps slow climate change?', 'ir al cole andando o en bici|anar a l’escola a peu o amb bici|walking or cycling to school', ['dejar luces encendidas|deixar llums enceses|leaving lights on', 'tirar comida|tirar menjar|throwing food away'], 'Así no se queman combustibles.|Així no es cremen combustibles.|No fuel gets burnt.'),
    M('¿Qué le pasa al hielo de los polos por el calentamiento?|Què li passa al gel dels pols per l’escalfament?|What happens to polar ice because of warming?', 'se derrite|es fon|it melts', ['crece|creix|it grows', 'se vuelve azul|es torna blau|it turns blue'], 'Con más calor, el hielo se funde.|Amb més calor, el gel es fon.|More heat melts ice.'),
    TF('Los árboles ayudan a limpiar el aire.|Els arbres ajuden a netejar l’aire.|Trees help clean the air.', true, 'Toman el dióxido de carbono del aire.|Prenen el diòxid de carboni de l’aire.|They take carbon dioxide from the air.'),
    M('¿Qué fenómeno es más frecuente por el cambio climático?|Quin fenomen és més freqüent pel canvi climàtic?|Which event is becoming more common because of climate change?', 'olas de calor|onades de calor|heatwaves', ['días más largos|dies més llargs|longer days', 'menos estrellas|menys estreles|fewer stars'], 'La Tierra está más caliente.|La Terra està més calenta.|The Earth is warmer.'),
    TF('El cambio climático solo afecta a los animales de los polos.|El canvi climàtic només afecta els animals dels pols.|Climate change only affects polar animals.', false, 'Nos afecta a todos: también a las personas y a las cosechas.|Ens afecta a tots: també a les persones i a les collites.|It affects everyone: people and crops too.'),
  ]),
  '2P-CM-14': lesson(['El agua dulce que podemos beber es poca y muy valiosa. No hay que malgastarla.|L’aigua dolça que podem beure és poca i molt valuosa. No cal malgastar-la.|The fresh water we can drink is scarce and very precious. We must not waste it.', 'Trucos para ahorrar: cerrar el grifo al lavarse los dientes, ducharse en lugar de bañarse y arreglar los grifos que gotean.|Trucs per a estalviar: tancar l’aixeta en rentar-se les dents, dutxar-se en lloc de banyar-se i arreglar les aixetes que gotegen.|Tips to save water: turn off the tap while brushing your teeth, shower instead of bathing, and fix dripping taps.'],
    '¿Qué gasta menos agua?|Què gasta menys aigua?|Which uses less water?', ['Una bañera llena usa mucha agua.|Una banyera plena usa molta aigua.|A full bath uses a lot of water.', 'Una ducha corta.|Una dutxa curta.|A short shower.'], [
    M('Mientras te lavas los dientes, ¿qué haces con el grifo?|Mentre et rentes les dents, què fas amb l’aixeta?|While brushing your teeth, what do you do with the tap?', 'Lo cierro|La tanque|Turn it off', ['Lo dejo abierto|La deixe oberta|Leave it running', 'Lo abro más|L’òbric més|Turn it up'], 'Solo lo abres para enjuagarte.|Només l’obris per a esbandir-te.|Only turn it on to rinse.'),
    M('Un grifo gotea. ¿Qué hay que hacer?|Una aixeta goteja. Què cal fer?|A tap is dripping. What should be done?', 'Avisar para arreglarlo|Avisar per a arreglar-la|Get it fixed', ['Nada|Res|Nothing', 'Poner un cubo para siempre|Posar un poal per sempre|Put a bucket under it forever'], 'Gota a gota se pierden muchos litros.|Gota a gota es perden molts litres.|Drop by drop, many litres are lost.'),
    TF('El agua dulce de la Tierra es muy abundante y no se acaba.|L’aigua dolça de la Terra és molt abundant i no s’acaba.|Fresh water on Earth is plentiful and never runs out.', false, 'La mayor parte del agua es salada.|La major part de l’aigua és salada.|Most water is salty.'),
    M('¿Cuál es una buena idea para regar las plantas?|Quina és una bona idea per a regar les plantes?|What is a good idea for watering plants?', 'Usar el agua de lavar la fruta|Usar l’aigua de llavar la fruita|Use the water from washing fruit', ['Regar al mediodía con mucho sol|Regar a migdia amb molt de sol|Water at noon in full sun', 'Dejar la manguera abierta|Deixar la mànega oberta|Leave the hose running'], 'Reutilizar el agua ahorra.|Reutilitzar l’aigua estalvia.|Reusing water saves it.'),
    M('¿Por qué es importante ahorrar agua?|Per què és important estalviar aigua?|Why is it important to save water?', 'Porque el agua potable es escasa|Perquè l’aigua potable és escassa|Because drinkable water is scarce', ['Porque sabe mal|Perquè té mal gust|Because it tastes bad', 'Porque no sirve para nada|Perquè no servix per a res|Because it is useless'], 'Muchas personas no tienen agua limpia.|Moltes persones no tenen aigua neta.|Many people have no clean water.'),
    M('¿Qué electrodoméstico se debe poner lleno para ahorrar agua?|Quin electrodomèstic s’ha de posar ple per a estalviar aigua?|Which appliance should be run full to save water?', 'el lavavajillas|el rentaplats|the dishwasher', ['la nevera|el frigorífic|the fridge', 'la tostadora|la torradora|the toaster'], 'Gasta lo mismo medio vacío que lleno.|Gasta el mateix mig buit que ple.|It uses the same water half empty as full.'),
  ]),
  '2P-CM-15': lesson(['En la cesta de la compra hay bienes de primera necesidad (alimentos, agua, ropa, productos de higiene) y otros que no son imprescindibles (juguetes, golosinas).|En la cistella de la compra hi ha béns de primera necessitat (aliments, aigua, roba, productes d’higiene) i altres que no són imprescindibles (joguets, llepolies).|A shopping basket holds essentials (food, water, clothes, hygiene products) and things that are not essential (toys, sweets).', 'Comprar con responsabilidad es comprar lo que necesitamos, sin malgastar y eligiendo productos con menos envases.|Comprar amb responsabilitat és comprar el que necessitem, sense malgastar i triant productes amb menys envasos.|Shopping responsibly means buying what we need, not wasting, and choosing products with less packaging.'],
    '¿Qué es más necesario, pan o un juguete?|Què és més necessari, pa o un joguet?|Which is more necessary, bread or a toy?', ['Sin comida no podemos vivir.|Sense menjar no podem viure.|We cannot live without food.', 'El pan es un bien de primera necesidad.|El pa és un bé de primera necessitat.|Bread is an essential.'], [
    M('¿Cuál es un bien de primera necesidad?|Quin és un bé de primera necessitat?|Which is an essential item?', 'el agua|l’aigua|water', ['un videojuego|un videojoc|a video game', 'un cromo|un cromo|a sticker'], 'Lo necesitamos para vivir.|El necessitem per a viure.|We need it to live.'),
    M('¿Qué es mejor llevar al supermercado?|Què és millor portar al supermercat?|What is best to take to the supermarket?', 'una bolsa reutilizable|una bossa reutilitzable|a reusable bag', ['muchas bolsas de plástico nuevas|moltes bosses de plàstic noves|lots of new plastic bags', 'nada y comprar bolsas cada vez|res i comprar bosses cada vegada|nothing, and buy bags every time'], 'Se usa muchas veces.|S’usa moltes vegades.|It is used many times.'),
    M('Antes de ir a comprar, ¿qué conviene hacer?|Abans d’anar a comprar, què convé fer?|Before going shopping, what is a good idea?', 'Hacer una lista|Fer una llista|Make a list', ['Ir con hambre|Anar amb fam|Go hungry', 'Comprar sin mirar|Comprar sense mirar|Buy without looking'], 'Así compras solo lo que necesitas.|Així compres només el que necessites.|Then you only buy what you need.'),
    TF('Comprar más de lo que necesitamos puede hacer que tiremos comida.|Comprar més del que necessitem pot fer que tirem menjar.|Buying more than we need can lead to throwing food away.', true, 'La comida que no se usa se estropea.|El menjar que no s’usa es fa malbé.|Unused food goes off.'),
    M('¿Qué fruta tiene menos envase?|Quina fruita té menys envàs?|Which fruit has less packaging?', 'la fruta a granel|la fruita a granel|loose fruit', ['la fruta en bandeja con plástico|la fruita en safata amb plàstic|fruit on a plastic-wrapped tray', 'la fruta en lata|la fruita en llanda|tinned fruit'], 'A granel = sin empaquetar.|A granel = sense empaquetar.|Loose = not packaged.'),
    M('Las golosinas, ¿son de primera necesidad?|Les llepolies, són de primera necessitat?|Are sweets essential?', 'No|No|No', ['Sí|Sí|Yes'], 'Podemos vivir sin ellas.|Podem viure sense elles.|We can live without them.'),
  ]),
  '2P-CM-16': lesson(['Antes de un experimento hacemos una predicción: decimos qué creemos que pasará. Después lo comprobamos y comparamos lo que pensábamos con lo que ha pasado.|Abans d’un experiment fem una predicció: diem què creiem que passarà. Després ho comprovem i comparem el que pensàvem amb el que ha passat.|Before an experiment we make a prediction: we say what we think will happen. Then we test it and compare what we thought with what happened.', 'Equivocarse en la predicción no es un fallo: también se aprende.|Equivocar-se en la predicció no és un error: també s’aprén.|A wrong prediction is not a failure: you still learn something.'],
    '¿Flotará una manzana en el agua?|Surarà una poma en l’aigua?|Will an apple float in water?', ['Predicción: «creo que se hundirá porque pesa».|Predicció: «crec que s’enfonsarà perquè pesa».|Prediction: "I think it will sink because it is heavy".', 'Comprobación: ¡flota! Mi predicción no era correcta y he aprendido algo.|Comprovació: sura! La meua predicció no era correcta i he aprés alguna cosa.|Test: it floats! My prediction was wrong and I learnt something.'], [
    M('¿Qué es una predicción?|Què és una predicció?|What is a prediction?', 'Lo que crees que va a pasar|El que creus que passarà|What you think will happen', ['Lo que ya ha pasado|El que ja ha passat|What has already happened', 'Un dibujo|Un dibuix|A drawing'], 'Se hace antes de comprobar.|Es fa abans de comprovar.|It comes before the test.'),
    M('Pongo un cubito de hielo en la mano. Predicción correcta:|Pose un glaçó en la mà. Predicció correcta:|I hold an ice cube in my hand. A good prediction:', 'Se derretirá|Es fondrà|It will melt', ['Crecerá|Creixerà|It will grow', 'Se volverá piedra|Es tornarà pedra|It will turn to stone'], 'La mano está caliente.|La mà està calenta.|Your hand is warm.'),
    M('¿Qué haces después de comprobar?|Què fas després de comprovar?|What do you do after testing?', 'Comparar con la predicción|Comparar amb la predicció|Compare with the prediction', ['Borrar la predicción|Esborrar la predicció|Rub out the prediction', 'Inventar el resultado|Inventar el resultat|Make up the result'], 'Así ves si acertaste.|Així veus si vas encertar.|Then you see if you were right.'),
    TF('Si mi predicción falla, el experimento no sirve.|Si la meua predicció falla, l’experiment no servix.|If my prediction is wrong, the experiment is useless.', false, 'También aprendemos de lo que no esperábamos.|També aprenem del que no esperàvem.|We learn from the unexpected too.'),
    M('Para saber si una planta necesita luz, ponemos una al sol y otra…|Per a saber si una planta necessita llum, posem una al sol i una altra…|To find out if a plant needs light, we put one in the sun and another…', 'a oscuras, con la misma agua|a les fosques, amb la mateixa aigua|in the dark, with the same water', ['al sol con más agua|al sol amb més aigua|in the sun with more water', 'en el congelador|en el congelador|in the freezer'], 'Solo debe cambiar una cosa: la luz.|Només ha de canviar una cosa: la llum.|Only one thing should change: the light.'),
    M('¿Dónde apuntamos los resultados?|On apuntem els resultats?|Where do we record results?', 'en una tabla o un cuaderno|en una taula o un quadern|in a table or a notebook', ['en ningún sitio|en cap lloc|nowhere', 'en la pared con rotulador|en la paret amb retolador|on the wall in marker'], 'Así no se olvidan.|Així no s’obliden.|So they are not forgotten.'),
  ]),
  '2P-CM-17': lesson(['La ciencia la hacen mujeres y hombres de todo el mundo. Por ejemplo, Marie Curie estudió la radiactividad y Margarita Salas investigó cómo funcionan los virus.|La ciència la fan dones i homes de tot el món. Per exemple, Marie Curie va estudiar la radioactivitat i Margarita Salas va investigar com funcionen els virus.|Science is done by women and men all over the world. For example, Marie Curie studied radioactivity and Margarita Salas researched how viruses work.', 'Hay muchas profesiones científicas: médica, ingeniero, bióloga, astronauta, química, informático…|Hi ha moltes professions científiques: metgessa, enginyer, biòloga, astronauta, química, informàtic…|There are many science jobs: doctor, engineer, biologist, astronaut, chemist, computer scientist…'],
    '¿Quién estudia los animales y las plantas?|Qui estudia els animals i les plantes?|Who studies animals and plants?', ['«Bio» significa vida.|«Bio» significa vida.|"Bio" means life.', 'Un biólogo o una bióloga.|Un biòleg o una biòloga.|A biologist.'], [
    M('¿Quién diseña puentes y edificios?|Qui dissenya ponts i edificis?|Who designs bridges and buildings?', 'una ingeniera o un ingeniero|una enginyera o un enginyer|an engineer', ['un pastelero|un pastisser|a baker', 'una pintora|una pintora|a painter'], 'Usa matemáticas y ciencia.|Usa matemàtiques i ciència.|They use maths and science.'),
    M('¿Quién viaja al espacio?|Qui viatja a l’espai?|Who travels into space?', 'una astronauta o un astronauta|una astronauta o un astronauta|an astronaut', ['un cartero|un carter|a postman', 'una peluquera|una perruquera|a hairdresser'], '«Astro» significa estrella.|«Astro» significa estrela.|"Astro" means star.'),
    TF('La ciencia solo la pueden hacer los hombres.|La ciència només la poden fer els homes.|Only men can do science.', false, 'Muchas grandes científicas, como Marie Curie, lo demuestran.|Moltes grans científiques, com Marie Curie, ho demostren.|Many great women scientists, such as Marie Curie, prove otherwise.'),
    M('¿Qué estudió Marie Curie?|Què va estudiar Marie Curie?|What did Marie Curie study?', 'la radiactividad|la radioactivitat|radioactivity', ['las plantas del jardín|les plantes del jardí|garden plants', 'los coches|els cotxes|cars'], 'Ganó dos premios Nobel.|Va guanyar dos premis Nobel.|She won two Nobel prizes.'),
    M('¿Qué hace un médico o una médica?|Què fa un metge o una metgessa?|What does a doctor do?', 'Cura a las personas enfermas|Cura les persones malaltes|Treats sick people', ['Construye robots|Construïx robots|Builds robots', 'Estudia las estrellas|Estudia les estreles|Studies the stars'], 'Cuida de nuestra salud.|Cuida de la nostra salut.|They look after our health.'),
    M('¿Quién crea programas de ordenador?|Qui crea programes d’ordinador?|Who creates computer programs?', 'una informática o un informático|una informàtica o un informàtic|a computer scientist', ['un jardinero|un jardiner|a gardener', 'una cantante|una cantant|a singer'], 'Escribe órdenes para el ordenador.|Escriu ordres per a l’ordinador.|They write instructions for the computer.'),
  ]),
};
export default P;
